// Spatial selection shared by touch D-pad and keyboard menus.
export function nextCommand(rects,index,direction){if(!rects.length)return -1;if(index<0||!rects[index])return 0;const vertical=direction==='up'||direction==='down',sign=direction==='up'||direction==='left'?-1:1,origin=rects[index],axis=vertical?'y':'x',cross=vertical?'x':'y';const candidates=rects.map((r,i)=>({i,d:(r[axis]-origin[axis])*sign,c:Math.abs(r[cross]-origin[cross])})).filter(r=>r.i!==index&&r.d>3).sort((a,b)=>(a.d+a.c*3)-(b.d+b.c*3));if(candidates.length)return candidates[0].i;const wrap=rects.map((r,i)=>({i,a:r[axis]*sign,c:Math.abs(r[cross]-origin[cross])})).filter(r=>r.i!==index).sort((a,b)=>(a.a+a.c*3)-(b.a+b.c*3));return wrap[0]?.i??index;}
